import { registerAndGetData } from '@/plugins/data'
import { getExportSettingsFilename } from '../utils'

export interface AboutPageAction {
  icon: string
  iconSize?: number
  disabled?: boolean
  name: string
  displayName: string
  actionName?: string
  run: (event?: MouseEvent) => void | Promise<void>
}

export const builtInActions: AboutPageAction[] = [
  {
    icon: 'mdi-inbox-arrow-up-outline',
    name: 'exportSettings',
    displayName: '导出设置',
    actionName: 'Export Settings',
    run: async () => {
      const { settings } = await import('@/core/settings')
      const { DownloadPackage } = await import('@/core/download')
      const fileName = await getExportSettingsFilename()
      DownloadPackage.single(`${fileName}.json`, JSON.stringify(settings, undefined, 2))
    },
  },
  {
    icon: 'mdi-inbox-arrow-down-outline',
    name: 'importSettings',
    displayName: '导入设置',
    actionName: 'Import Settings',
    run: async () => {
      const { logError } = await import('@/core/utils/log')
      const { pickFile } = await import('@/core/file-picker')
      const { Toast } = await import('@/core/toast')
      const files = await pickFile({
        accept: '*.json',
      })
      if (files.length === 0) {
        return
      }
      const [file] = files
      try {
        const { stageSettingsImport } = await import('@/core/settings/read')
        if (file.size > 64 * 1024 * 1024) {
          throw new Error('设置文件超过 64 MiB，请使用设置面板导出的文件。')
        }
        let importedSettings: unknown
        try {
          importedSettings = JSON.parse((await file.text()).replace(/^\uFEFF/, ''))
        } catch {
          throw new Error('设置文件不是有效的 JSON，现有配置未改动。')
        }
        stageSettingsImport(importedSettings)
        Toast.success('设置已接收，正在刷新页面应用...', '导入设置')
        window.location.reload()
      } catch (error) {
        logError(error)
      }
    },
  },
]
export const [aboutPageActions] = registerAndGetData('settingsPanel.about.actions', builtInActions)
